INSERT INTO t_p76941956_laugh_yoga_landing.site_content (key, value) VALUES
('hero', $j${"badge":"в группе — 15–20 человек · Екатеринбург","title":"Ржать полезно","text":"100 минут хохота вместо ещё одного вечера с телефоном. Диафрагма включается — мозг сам меняет кортизол на эндорфины.","button":"Хочу смеяться","note":"Занятие — 700 ₽. Не смешно — второе бесплатно.","hint":"садись на мягкий пол · дыши · «хо-хо, ха-ха»"}$j$::jsonb),
('what', $j${"badge":"Метод","title":"Что такое","title_accent":"йога смеха","text":"Практику придумал врач Мадан Катария в 1995 году. Идея простая: мы смеёмся телом, а не поводом. Начинаем через упражнения — и смех становится настоящим сам собой.","points":[{"icon":"Wind","title":"Смех + дыхание","text":"Смеховые упражнения соединяются с йоговским дыханием. Тело не отличает «настоящий» смех от игрового — эффект одинаковый."},{"icon":"Users","title":"Всегда в группе","text":"Зрительный контакт и игра запускают заразительный смех. Через пару минут никто уже не притворяется."},{"icon":"Sparkles","title":"Без гибкости и позы лотоса","text":"Не нужно уметь садиться на шпагат. Нужно только желание выдохнуть и немного подурачиться."}]}$j$::jsonb),
('how', $j${"badge":"Формат","title":"Как проходит занятие","text":"100 минут. Никакой сцены и «выступлений» — только вы, группа и много смеха. Приходите в удобной одежде, остальное на нас.","image":"https://cdn.poehali.dev/projects/4626b584-3db2-4647-9c5a-24f1113590fb/files/4f1127df-e4d1-4668-be21-abf9a82c8ead.jpg","steps":[{"t":"Настройка","time":"0–15 мин","text":"Знакомимся, снимаем «взрослую серьёзность». Лёгкая разминка и дыхание, чтобы тело проснулось."},{"t":"Смеховые упражнения","time":"15–55 мин","text":"Игровые сценки, хлопки, «хо-хо, ха-ха». Смех из игрового переходит в настоящий и заразительный."},{"t":"Смеховая медитация","time":"55–80 мин","text":"Свободный смех без поводов, затем тишина. Самая яркая часть — тело отпускает напряжение."},{"t":"Расслабление","time":"80–100 мин","text":"Лёжа на мягком полу дышим и отдыхаем. Уходите лёгкими, с ясной головой и улыбкой."}]}$j$::jsonb),
('benefits', $j${"badge":"Польза","title":"Что забираете","title_accent":"с собой","stats":[{"n":"100","s":"мин чистого смеха"},{"n":"−40%","s":"ощущаемого стресса"},{"n":"15–20","s":"человек в группе"},{"n":"700 ₽","s":"пробное занятие"}],"items":[{"icon":"HeartPulse","t":"Меньше стресса","d":"Смех снижает кортизол и мышечные зажимы. Тело выдыхает вслед за вами."},{"icon":"Brain","t":"Ясная голова","d":"Приток кислорода и эндорфинов — после занятия думается легче и спокойнее."},{"icon":"Lungs","t":"Дыхание и лёгкие","d":"Диафрагмальное дыхание тренирует лёгкие лучше, чем офисные вздохи."},{"icon":"Moon","t":"Крепкий сон","d":"Сброшенное напряжение помогает засыпать быстрее и спать глубже."},{"icon":"Smile","t":"Настроение","d":"Заряд хорошего настроения держится не час, а несколько дней."},{"icon":"Zap","t":"Энергия","d":"Мягкая физнагрузка без спортзала: пресс и лицо работают за вас."}]}$j$::jsonb),
('coach', $j${"badge":"Ведущий","name":"Виталий Володин","quote":"«Я пришёл в йогу смеха выгоревшим и уставшим — а остался, потому что впервые за годы почувствовал лёгкость. Теперь помогаю людям Екатеринбурга находить эту лёгкость за один час.»","photo":"/coach-vitaly.png","button":"Прийти на занятие","facts":["Сертифицированный ведущий по методу Laughter Yoga International","Более 6 лет практики и 300+ проведённых занятий","Работаю с группами, парами и корпоративными командами"]}$j$::jsonb),
('reviews', $j${"badge":"Отзывы","title":"Люди","title_accent":"после","title_end":"занятия","items":[{"name":"Ольга","role":"бухгалтер, 34","text":"Шла со скепсисом — «как это смеяться по команде?». Через десять минут ржала так, что болел живот. Впервые за год выключилась голова."},{"name":"Дмитрий","role":"айтишник, 29","text":"Отличная перезагрузка после недели за монитором. Уходишь пустой в хорошем смысле, спишь потом как в детстве."},{"name":"Наталья","role":"мама в декрете, 38","text":"Мой личный час без телефона и без забот. Группа тёплая, ведущий бережный. Хожу как на терапию, только весело."},{"name":"Сергей","role":"предприниматель, 45","text":"Привёл всю команду на корпоратив — работали потом дружнее. Оказалось, вместе поржать полезнее любого тимбилдинга."}]}$j$::jsonb),
('pricing', $j${"badge":"Цены","title":"Выбирайте формат","button":"Записаться","plans":[{"name":"Пробное","price":"700 ₽","unit":"одно занятие","note":"Не смешно — второе бесплатно","features":["100 минут практики","Всё оборудование включено","Знакомство с методом"],"highlight":false},{"name":"Абонемент","price":"3 500 ₽","unit":"5 занятий","note":"Самый популярный","features":["5 занятий в удобные дни","Заморозка на болезнь","Место в группе за вами"],"highlight":true},{"name":"Корпоратив","price":"от 12 000 ₽","unit":"выезд на команду","note":"До 20 человек","features":["Выезд в ваш офис или зал","Программа под задачу","Тимбилдинг без неловкости","Гибкое время"],"highlight":false}]}$j$::jsonb),
('faq', $j${"badge":"Вопросы","title":"Частые вопросы","items":[{"q":"Мне не смешно по команде — это точно сработает?","a":"Да. Мы начинаем со смеховых упражнений, а не с шуток. Тело не отличает игровой смех от настоящего, и уже через несколько минут в группе смех становится искренним и заразительным."},{"q":"Нужна ли физическая подготовка или гибкость?","a":"Нет. Это не про позы и растяжку. Всё, что нужно — удобная одежда и желание выдохнуть. Практика подходит людям любого возраста и уровня подготовки."},{"q":"Что взять с собой?","a":"Только себя и удобную одежду, в которой не жалко подвигаться. Коврики и всё остальное оборудование уже на месте."},{"q":"Есть ли противопоказания?","a":"Практику стоит согласовать с врачом при тяжёлых сердечно-сосудистых заболеваниях, эпилепсии, грыжах и в поздние сроки беременности. Если сомневаетесь — напишите нам перед записью."},{"q":"Что если приду и мне не понравится?","a":"Если после пробного занятия вы не почувствовали пользы — приходите на второе бесплатно. Мы уверены в методе."},{"q":"Где проходят занятия?","a":"В уютной студии в центре Екатеринбурга. Точный адрес и время ближайшей группы пришлём после записи."}]}$j$::jsonb),
('schedule', $j${"enabled":true,"badge":"Расписание","title":"Ближайшие занятия","text":"Выберите удобный день и запишитесь — места в группе ограничены.","items":[{"day":"Вторник","time":"19:00","title":"Вечерняя группа","place":"Студия в центре Екатеринбурга"},{"day":"Четверг","time":"19:00","title":"Вечерняя группа","place":"Студия в центре Екатеринбурга"},{"day":"Суббота","time":"11:00","title":"Утренняя группа выходного дня","place":"Студия в центре Екатеринбурга"}]}$j$::jsonb),
('contacts', $j${"badge":"Запись","title":"Приходите","title_accent":"смеяться","text":"Оставьте заявку — подберём удобное время и забронируем место в ближайшей группе. Занятие всего 700 ₽.","items":[{"icon":"MapPin","label":"Студия в центре Екатеринбурга","sub":"Адрес пришлём после записи"},{"icon":"Phone","label":"+7 (343) 000-00-00","sub":"Пн–Вс, 10:00–21:00"},{"icon":"Send","label":"@hohohaha_ekb","sub":"Пишите в Telegram"}]}$j$::jsonb),
('footer', $j${"description":"Йога смеха в Екатеринбурге. Садись на мягкий пол · дыши · «хо-хо, ха-ха».","legal":"ИП Володин Виталий Эдуардович\nОГРНИП 325665800163492","tagline":"Ржать полезно"}$j$::jsonb)
